entries[25894] = { ["name"] = "Großer Segen der Weisheit", ["text"] = "230 Mana 40 Meter Reichweite\nSofort\nReagenzien:\nSymbol der Könige\nBelegt alle Mitglieder einer Gruppe oder eines Schlachtzuges, die dieselbe Klasse wie das Ziel haben, mit dem großen Segen der Weisheit. Der große Segen der Weisheit stellt 15 Min. lang alle 5 Sekunden 30 Mana wieder her. Spieler können pro Paladin immer nur mit einem einzigen Segen belegt sein." }
entries[25895] = { ["name"] = "Großer Segen der Rettung", ["text"] = "16% von Grundmana 40 Meter Reichweite\nSofort\nReagenzien:\nSymbol der Könige\nBelegt alle Mitglieder einer Gruppe oder eines Schlachtzuges, die dieselbe Klasse wie das Ziel haben, mit dem großen Segen der Rettung. Der große Segen der Rettung reduziert die Bedrohung, die das Ziel erzeugt, 15 Min. lang um 30%. Spieler können pro Paladin immer nur mit einem einzigen Segen belegt sein." }
