entries[25898] = { ["name"] = "Großer Segen der Könige", ["text"] = "150 Mana 40 Meter Reichweite\nSofort\nReagenzien:\nSymbol der Könige\nBelegt alle Mitglieder einer Gruppe oder eines Schlachtzuges, die dieselbe Klasse wie das Ziel haben, mit dem großen Segen der Könige. Der große Segen der Könige erhöht alle Werte des Ziels 15 Min. lang um 10%. Spieler können pro Paladin immer nur mit einem einzigen Segen belegt sein." }
entries[25899] = { ["name"] = "Großer Segen des Refugiums", ["text"] = "270 Mana 40 Meter Reichweite\nSofort\nReagenzien:\nSymbol der Könige\nBelegt alle Mitglieder einer Gruppe oder eines Schlachtzuges, die dieselbe Klasse wie das Ziel haben, mit dem großen Segen des Refugiums. Der große Segen des Refugiums reduziert sämtlichen beim Ziel verursachten Schaden 15 Min. lang um 24. Zusätzlich verursacht ein Ziel, wenn es einen Angriff blockt, beim Angreifer 35 Heiligschaden. Spieler können pro Paladin immer nur mit einem einzigen Segen belegt sein." }
